GimCorpus.put(442,0,[[1,5,"ואם הביאה קרבנה בתוך מלאת וכו' עד בתוך מלאת של ולד. א\"א זה תימה גדול אם שלחה קרבנותיה תוך מלאת למה לא יצאה ומאי שנא מחטאת חלב ודם שהטמא משלח אותה ומקריבין לה:",1,0],[1,10,"היו עליה חמש לידות ודאות וכו'. א\"א הא דלאו כהלכתא שהרי משנה אחרונה אמרו אין השאר עליה חובה ואולי יש הפרש בין משהה קרבנותיה מזידה למשהה אנוסה:",1,0],[2,4,"עכו\"ם שראה קרי ואחר כך נתגייר וכו'. א\"א מפרש בתוספתא אימתי בזמן שנתגייר כשהוא מהול אבל מל ואחר כך ראה תולין לו כל זמן שמצטער:",1,0],[4,2,"ואחר כך מביא את האשם. א\"א אין כאן אח\"כ אלא במקום שמניף שם היה סומך ותיכף התנופה היתה הסמיכה וכך היא שנויה בתוספתא כאשר הגהתי למעלה:",1,0]]);
